-- ===========================================================================
-- otbi-atd db/68 : Transaction Distribution - All -- chunked + service account
--
-- The saved analysis (private catalog folder of saljaaidi@ -- service account
-- gets Path-not-found; runs needed personal MFA approvals) selects the WHOLE
-- Receivables - Transactions Real Time SA with NO filter: 461,678 rows,
-- DOWNLOAD phase 889s of the 900s timeout. Converted to the chunked logical-
-- SQL extract (runner/sqlchunks.py): 19 chunks partitioning the space by
-- construction (dim accounting-date IS NULL + past guard + Dec-2025 split 4
-- ways by Accounting Class w/ null-safe catch-all + 12 monthly 2026 ranges +
-- open >= 2027 tail), positional #N headers (two logical columns both export
-- as 'Accounting Date'), parallel 6, min_rows floor 300k. Probed under the
-- SERVICE account: SA access OK, chunk counts byte-exact vs the 2026-08-14
-- personal-session load, 89-195s per chunk. requested_by cleared so runs use
-- the service account -- no more personal MFA. Rerunnable.
-- Rollover note: the 2026 monthly ranges + Dec-2025 split are baked into the
-- chunks list -- extend it when 2027 volume grows (the >= 2027 tail catches
-- everything until then, so nothing is ever silently dropped).
-- ===========================================================================
SET DEFINE OFF
SET SQLBLANKLINES ON

UPDATE prod.atd_otbi_jobs
   SET params_json = q'[{"_atd_sql_chunks":{"sql":"SET VARIABLE PREFERRED_CURRENCY='User Preferred Currency 1'; SELECT 0 s_0, \"Receivables - Transactions Real Time\".\"- General Information\".\"Transaction ID\" s_1, \"Receivables - Transactions Real Time\".\"- General Information\".\"Transaction Number\" s_2, \"Receivables - Transactions Real Time\".\"- Line Information\".\"Unit Of Measure Code\" s_3, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounted\" s_4, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" s_5, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Distribution Percentage\" s_6, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Date\" s_7, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Distribution Comments\" s_8, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"GL Posted Date\" s_9, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Posting Control Id\" s_10, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Receivables  Code Combination Description\" s_11, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Receivables Concatenated Segments\" s_12, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Alternate Code Combination\" s_13, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Account Type Code\" s_14, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Distribution Entered Amount\" s_15, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Distribution Accounted Amount\" s_16, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Ledger Currency\" s_17, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Document Currency Name\" s_18, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Document Currency\" s_19, \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Month\" s_20, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Last Updated By\" s_21, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Last Updated By User Name\" s_22, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Last Update Date\" s_23, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Created By\" s_24, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Created By User Name\" s_25, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Creation Date\" s_26, \"Receivables - Transactions Real Time\".\"- Distribution Cost Center Segment Value\".\"Distribution Cost Center Description\" s_27, \"Receivables - Transactions Real Time\".\"- Distribution Cost Center Segment Value\".\"Distribution Cost Center Code\" s_28, \"Receivables - Transactions Real Time\".\"- Distribution Natural Account Segment Value\".\"Distribution Natural Account Description\" s_29, \"Receivables - Transactions Real Time\".\"- Distribution Natural Account Segment Value\".\"Distribution Natural Account Code\" s_30 FROM \"Receivables - Transactions Real Time\" WHERE ({chunk})","chunks":["\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" IS NULL","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2025-12-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Revenue'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Receivable'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Tax'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND (\"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" NOT IN ('Revenue', 'Receivable', 'Tax') OR \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" IS NULL)","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-02-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-02-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-03-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-03-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-04-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-04-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-05-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-05-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-06-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-06-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-07-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-07-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-08-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-08-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-09-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-09-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-10-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-10-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-11-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-11-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-12-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2027-01-01'","\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2027-01-01'"],"headers":{"#2":"Transaction ID","#3":"Transaction Number","#4":"UOM Code","#5":"Accounted","#6":"Accounting Class","#7":"Distribution Percentage","#8":"Accounting Date","#9":"Distribution Comments","#10":"Posted Date","#11":"Posting Control Identifier","#12":"Receivables  Code Combination Description","#13":"Receivables Concatenated Segments","#14":"Alternate Code Combination","#15":"Account Type Code","#16":"Distribution Entered Amount","#17":"Distribution Accounted Amount","#18":"Ledger Currency","#19":"Document Currency Name","#20":"Document Currency","#21":"Calendar Month","#22":"Last Updated By","#23":"Last Updated By User Name","#24":"Invoice Last Update Date","#25":"Created By","#26":"Created By User Name","#27":"Creation Date","#28":"Distribution Cost Center Description","#29":"Distribution Cost Center Code","#30":"Distribution Natural Account Description","#31":"Distribution Natural Account Code"},"min_rows":300000,"retries":1,"parallel":6}}]',
       requested_by = NULL
 WHERE job_name = 'Transaction Distribution - All';

COMMIT;

SELECT job_name, enabled, requested_by, LENGTH(params_json) params_len,
       CASE WHEN params_json IS JSON THEN 'VALID' ELSE 'BAD' END js
  FROM prod.atd_otbi_jobs
 WHERE job_name = 'Transaction Distribution - All';
